import itertools,random,json,math,collections,hashlib
from vs import corpus,ivtff,refcorpus,judge

def ws(pgs):
 return [w for p in pgs for l in p.lines if l.unit=='P' for w in l.words if not ivtff.uncertain(w) and w.isascii() and w.isalpha() and w.islower()]
tr,ev=corpus.split_pages('practice','zl'); counts=collections.Counter(ws(tr))
# Fix base-three digits by maximizing supported 4-char words in training, alphabetical tie-break.
def valid(w,a):
 if not (w.startswith('y') and 4<=len(w)<=49 and (len(w)-1)%3==0 and set(w[1:])<=set(a)):return False
 return all(sum(a.index(w[i+j])*3**(2-j) for j in range(3))<26 for i in range(1,len(w),3))
def enc(w,a):
 if not (1<=len(w)<=16 and w.isascii() and w.isalpha() and w.islower()):raise ValueError()
 return 'y'+''.join(''.join(a[ord(c)%97//3**d%3] for d in (2,1,0)) for c in w)
def dec(w,a):
 if not valid(w,a):raise ValueError()
 return ''.join(chr(97+sum(a.index(w[i+j])*3**(2-j) for j in range(3))) for i in range(1,len(w),3))
for s in ['a','z','hello','x'*16]:assert dec(enc(s,'abc'),'abc')==s
abc=''.join(sorted(set(''.join(counts))))
options=[]
for chars in itertools.combinations(abc,3):
 for perm in itertools.permutations(chars):
  a=''.join(perm); hit=sum(n for w,n in counts.items() if len(w)==4 and valid(w,a));options.append((hit,a))
best=max(q[0] for q in options); a=min(a for n,a in options if n==best)
codes=sorted(w for w in counts if not w.startswith('y')); words=' '.join(refcorpus.blocks_of('it_villani')).split(); train=words[:50000];test=words[50000:75000]; assert len(test)==25000
common=[w for w,n in sorted(collections.Counter(train).items(),key=lambda x:(-x[1],x[0]))[:1000]]
random.Random(19).shuffle(codes);lookup=dict(zip(common,codes)); assert len(lookup)==1000 and len(set(lookup.values()))==1000
for w in test:
 if 1<=len(w)<=16:assert dec(enc(w,a),a)==w
shapes={}
for name,w in [('train',ws(tr)),('zl_practice',ws(ev)),('it_practice',ws(corpus.split_pages('practice','it')[1]))]:
 shapes[name]={'tokens':len(w),'valid_tokens':sum(valid(x,a) for x in w),'valid_types':len({x for x in w if valid(x,a)}),'dictionary_hits':sum(x in lookup.values() for x in w)}
variants={}
for name in ('dictionary_only','escape_only','combined'):
 out=[];refused=0; nmap=0; nesc=0
 for w in test:
  if name!='escape_only' and w in lookup: out.append(lookup[w]);nmap+=1
  elif name!='dictionary_only' and len(w)<=16:out.append(enc(w,a));nesc+=1
  else:refused+=1
 variants[name]={'total':len(test),'refused':refused,'dictionary_tokens':nmap,'escape_tokens':nesc,'encoded_character_count':sum(map(len,out)),'max_encoded_word':max(map(len,out))}
print(json.dumps({'digits':a,'training_4char_hits':best,'tie_count':sum(n==best for n,a in options),'shapes':shapes,'dictionary_compressed_bits':judge.compressed_bits(judge.canonical({'map':{v:k for k,v in lookup.items()}})),'codec_alphabet_fixed_bits':15,'dictionary_source_count':len(codes),'variants':variants},indent=2))
